package com.vityarthi.library.repository;
import com.vityarthi.library.db.Database; import com.vityarthi.library.model.*; import java.sql.*; import java.util.*;
public class UserRepository {
 public void seed(){if(find("admin").isEmpty())insert(new Admin(0,"admin","admin123","System Admin"));if(find("librarian").isEmpty())insert(new Librarian(0,"librarian","lib123","Main Librarian"));if(find("alice").isEmpty())insert(new Member(0,"alice","alice123","Alice",2));if(find("bob").isEmpty())insert(new Member(0,"bob","bob123","Bob",1));}
 public void insert(User u){String q="INSERT INTO users(username,password,name,role,priority) VALUES(?,?,?,?,?)";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setString(1,u.getUsername());p.setString(2,u.getPassword());p.setString(3,u.getName());p.setString(4,u.getRole().name());p.setInt(5,u instanceof Member m?m.getPriority():0);p.executeUpdate();}catch(SQLException e){throw new IllegalArgumentException("Could not create user: "+e.getMessage());}}
 public Optional<User> find(String username){try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE username=?")){p.setString(1,username);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new IllegalStateException(e);}}
 public Optional<User> findById(long id){try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<User> all(){List<User> x=new ArrayList<>();try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM users ORDER BY id");ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));return x;}catch(SQLException e){throw new IllegalStateException(e);}}
 private User map(ResultSet r)throws SQLException{return switch(r.getString("role")){case "ADMIN"->new Admin(r.getLong("id"),r.getString("username"),r.getString("password"),r.getString("name"));case "LIBRARIAN"->new Librarian(r.getLong("id"),r.getString("username"),r.getString("password"),r.getString("name"));default->new Member(r.getLong("id"),r.getString("username"),r.getString("password"),r.getString("name"),r.getInt("priority"));};}
}